#include <iostream>
#include <vector>

// pre[i] is the volume of the first i levels, so pre[0] is 0
std::vector<long long> prefixSums(const std::vector<long long>& volume) {
    std::vector<long long> pre(volume.size() + 1, 0);
    for (std::size_t i = 0; i < volume.size(); ++i) {
        pre[i + 1] = pre[i] + volume[i];
    }
    return pre;
}

long long rangeSum(const std::vector<long long>& pre, int lo, int hi) {
    return pre[hi + 1] - pre[lo];
}

// A trade at one level changes every total after it
int addTrade(std::vector<long long>& pre, int level, long long qty) {
    int writes = 0;
    for (int j = level + 1; j < static_cast<int>(pre.size()); ++j) {
        pre[j] += qty;
        ++writes;
    }
    return writes;
}

int main() {
    const std::vector<long long> volume = {120, 40, 300, 75, 0, 210, 95, 60};
    std::vector<long long> pre = prefixSums(volume);
    std::cout << "levels 2 to 5: " << rangeSum(pre, 2, 5) << '\n';
    std::cout << "levels 0 to 7: " << rangeSum(pre, 0, 7) << '\n';
    std::cout << "level 4 alone: " << rangeSum(pre, 4, 4) << '\n';
    const int writes = addTrade(pre, 1, 25);
    std::cout << "a trade at level 1 rewrote " << writes << " totals\n";
    std::cout << "levels 2 to 5: " << rangeSum(pre, 2, 5) << '\n';
    std::cout << "levels 0 to 7: " << rangeSum(pre, 0, 7) << '\n';
    return 0;
}

