#include <iostream>
#include <string>
#include <vector>

struct Fenwick {
    std::vector<long long> tree;   // tree[0] is unused: positions start at 1

    explicit Fenwick(int n) : tree(n + 1, 0) {}

    void add(int i, long long delta) {   // position i gains delta
        while (i < static_cast<int>(tree.size())) {
            tree[i] += delta;
            i += i & -i;   // on to the next stretch that covers i
        }
    }

    long long prefix(int i) const {   // the total of positions 1 to i
        long long sum = 0;
        while (i > 0) {
            sum += tree[i];
            i -= i & -i;   // back to the stretch just before
        }
        return sum;
    }
};

int main() {
    int base = 0;     // the lowest price level, in ticks
    int levels = 0;
    std::cin >> base >> levels;
    Fenwick volume(levels);   // price p lives at position p - base + 1
    std::string op;
    int a = 0;
    int b = 0;
    while (std::cin >> op >> a >> b) {
        if (op == "T") {   // a trade of b lots at price a
            volume.add(a - base + 1, b);
        } else {           // the volume traded at prices a to b
            const long long v = volume.prefix(b - base + 1) - volume.prefix(a - base);
            std::cout << a << " to " << b << ": " << v << '\n';
        }
    }
    return 0;
}

