// The first position whose prefix reaches target: a lower bound, since prefixes only grow
int firstReaching(const Fenwick& f, int n, long long target) {
    int lo = 1;
    int hi = n;
    while (lo < hi) {
        const int mid = lo + (hi - lo) / 2;
        if (f.prefix(mid) >= target) {
            hi = mid;
        } else {
            lo = mid + 1;
        }
    }
    return lo;
}

