#include <algorithm>
#include <climits>
#include <iostream>
#include <string>
#include <vector>

struct MinTree {
    int n;
    std::vector<int> low;   // low[k]: the lowest price in node k's range

    explicit MinTree(const std::vector<int>& prices) : n(static_cast<int>(prices.size())), low(4 * n) {
        for (int i = 0; i < n; ++i) {
            set(1, 0, n - 1, i, prices[i]);
        }
    }

    // Node k covers minutes lo to hi. Its children are 2k (lo to mid) and 2k + 1 (mid + 1 to hi).
    void set(int k, int lo, int hi, int i, int price) {
        if (lo == hi) {
            low[k] = price;        // a leaf: one minute
            return;
        }
        const int mid = lo + (hi - lo) / 2;
        if (i <= mid) {
            set(2 * k, lo, mid, i, price);
        } else {
            set(2 * k + 1, mid + 1, hi, i, price);
        }
        low[k] = std::min(low[2 * k], low[2 * k + 1]);
    }

    int query(int k, int lo, int hi, int l, int r) const {
        if (r < lo || hi < l) {
            return INT_MAX;        // no overlap: a value that never wins
        }
        if (l <= lo && hi <= r) {
            return low[k];         // inside the query: use the stored answer
        }
        const int mid = lo + (hi - lo) / 2;
        return std::min(query(2 * k, lo, mid, l, r), query(2 * k + 1, mid + 1, hi, l, r));
    }
};

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> prices(n);
    for (int& p : prices) {
        std::cin >> p;
    }
    MinTree tree(prices);
    std::string op;
    int a = 0;
    int b = 0;
    while (std::cin >> op >> a >> b) {
        if (op == "C") {   // a correction: minute a's price was really b
            tree.set(1, 0, n - 1, a, b);
        } else {           // the low of minutes a to b
            const int low = tree.query(1, 0, n - 1, a, b);
            std::cout << "low of " << a << " to " << b << ": " << low << '\n';
        }
    }
    return 0;
}

