#include <algorithm>
#include <climits>
#include <iostream>
#include <string>
#include <vector>

struct LazyMinTree {
    std::vector<long long> low;       // the minimum of each node's range
    std::vector<long long> pending;   // an add this node's children haven't had yet

    LazyMinTree(int n, long long start) : low(4 * n, start), pending(4 * n, 0) {}

    void apply(int k, long long v) {   // add v to every value under node k, in O(1)
        low[k] += v;
        pending[k] += v;
    }

    void push(int k) {                 // hand node k's pending add to its children
        apply(2 * k, pending[k]);
        apply(2 * k + 1, pending[k]);
        pending[k] = 0;
    }

    void add(int k, int lo, int hi, int l, int r, long long v) {
        if (r < lo || hi < l) {
            return;
        }
        if (l <= lo && hi <= r) {
            apply(k, v);               // covered: stop here, the children can wait
            return;
        }
        push(k);
        const int mid = lo + (hi - lo) / 2;
        add(2 * k, lo, mid, l, r, v);
        add(2 * k + 1, mid + 1, hi, l, r, v);
        low[k] = std::min(low[2 * k], low[2 * k + 1]);
    }

    long long query(int k, int lo, int hi, int l, int r) {
        if (r < lo || hi < l) {
            return LLONG_MAX;
        }
        if (l <= lo && hi <= r) {
            return low[k];
        }
        push(k);
        const int mid = lo + (hi - lo) / 2;
        return std::min(query(2 * k, lo, mid, l, r), query(2 * k + 1, mid + 1, hi, l, r));
    }
};

int main() {
    int days = 0;
    long long start = 0;
    std::cin >> days >> start;
    LazyMinTree cash(days, start);
    std::string op;
    while (std::cin >> op) {
        int l = 0;
        int r = 0;
        std::cin >> l >> r;
        if (op == "A") {               // add v to every day from l to r
            long long v = 0;
            std::cin >> v;
            cash.add(1, 0, days - 1, l, r, v);
        } else {                       // the lowest balance from day l to day r
            const long long lowest = cash.query(1, 0, days - 1, l, r);
            std::cout << "days " << l << '-' << r << ": lowest " << lowest << '\n';
        }
    }
    return 0;
}

