    long long need = 0;
    while (std::cin >> l >> r >> need) {
        const long long peak = cores.query(1, 0, hours - 1, l, r);
        std::cout << "hours " << l << '-' << r << " need " << need << ": ";
        if (peak + need <= capacity) {
            cores.add(1, 0, hours - 1, l, r, need);
            std::cout << "accepted\n";
        } else {
            std::cout << "rejected, peak " << peak << '\n';
        }
    }
    std::cout << "busiest: " << cores.query(1, 0, hours - 1, 0, hours - 1) << '\n';
    return 0;
}
